func (con ArbWasm) ActivateProgram(c ctx, evm mech, value huge, program addr) (uint16, huge, error) {
	debug := evm.ChainConfig().DebugMode()
	runCtx := c.txProcessor.RunContext()
	programs := c.State.Programs()

	// charge the configurable activation gas upfront (default 0; raise to deter DOS or block activations entirely)
	activationGas, err := programs.ActivationGas()
	if err != nil {
		return 0, nil, err
	}
	if err := c.Burn(multigas.ResourceKindSingleDim, activationGas); err != nil {
		return 0, nil, err
	}

	// charge a fixed cost up front to begin activation
	if err := c.Burn(multigas.ResourceKindComputation, 1659168); err != nil {
		return 0, nil, err
	}
	version, codeHash, moduleHash, dataFee, takeAllGas, err := programs.ActivateProgram(evm, program, runCtx, debug)
	if takeAllGas {
		_ = c.BurnOut()
	}
	if err != nil {
		return version, dataFee, err
	}
	if err := con.payActivationDataFee(c, evm, value, dataFee); err != nil {
		return version, dataFee, err
	}
	return version, dataFee, con.ProgramActivated(c, evm, codeHash, moduleHash, program, dataFee, version)
}

