	}
	if err := c.State.NativeTokenOwners().Remove(addr, c.State.ArbOSVersion()); err != nil {
		return err
	}
	if c.State.ArbOSVersion() >= params.ArbosVersion_60 {
		return con.NativeTokenOwnerRemoved(c, evm, addr)
